// Mock customer database
const customers = {
  'CUST001': { customer_id: 'CUST001', name: 'Alice Johnson', email: 'alice.johnson@example.com', plan: 'Premium', status: 'active', country: 'USA' },
  'CUST002': { customer_id: 'CUST002', name: 'Bob Smith', email: 'bob.smith@example.com', plan: 'Basic', status: 'active', country: 'UK' },
  'CUST003': { customer_id: 'CUST003', name: 'Carla Mendes', email: 'carla.mendes@example.com', plan: 'Enterprise', status: 'suspended', country: 'Brazil' },
  'CUST004': { customer_id: 'CUST004', name: 'Daniel Kim', email: 'daniel.kim@example.com', plan: 'Premium', status: 'active', country: 'South Korea' },
  'CUST005': { customer_id: 'CUST005', name: 'Ewa Kowalski', email: 'ewa.kowalski@example.com', plan: 'Basic', status: 'churned', country: 'Poland' },
};

const raw = $json.customer_id;
const id = (raw === undefined || raw === null ? '' : String(raw)).trim().toUpperCase();

if (!id) {
  return { found: false, error: 'missing_customer_id', message: 'No customer_id was provided.' };
}

const record = customers[id];
if (!record) {
  return { found: false, error: 'not_found', message: `No customer found with ID ${id}.`, customer_id: id };
}

return { found: true, ...record };
